    <script>

        const money=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0);
        const safeNode=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;node.textContent=text??'';return node};
        function renderProjects(projects,emptyMessage='Belum ada informasi pembangunan yang dapat ditampilkan.'){const grid=document.querySelector('#project-grid');grid.replaceChildren();if(!projects.length){grid.append(safeNode('p','portal-data-empty',emptyMessage));grid.setAttribute('aria-busy','false');return}grid.setAttribute('aria-busy','false');projects.forEach(project=>{const card=document.createElement('article');card.className='bl-project-card';const top=document.createElement('div');top.className='bl-project-top';top.append(safeNode('span','',`Tahun ${project.year||'—'}`),safeNode('strong','',project.status||'Informasi'));const title=safeNode('h3','',project.title);const summary=safeNode('p','',project.summary||project.location||'Rincian pekerjaan tersedia di kantor desa.');const bottom=document.createElement('div');bottom.className='bl-project-bottom';bottom.append(safeNode('span','',project.funding||'Anggaran belum tersedia'));const detail=safeNode('button','bl-project-detail','Rincian pekerjaan');detail.type='button';bottom.append(detail);card.append(top,title,summary,bottom);const overlay=document.createElement('div');overlay.className='bl-project-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-label',`Rincian ${project.title}`);const head=document.createElement('div');head.className='bl-overlay-head';head.append(safeNode('strong','','Rincian pekerjaan'));const close=document.createElement('button');close.type='button';close.className='bl-overlay-close';close.setAttribute('aria-label','Tutup rincian');close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18"/></svg>';close.addEventListener('click',()=>overlay.classList.remove('open'));head.append(close);overlay.append(head);[['Lokasi',project.location],['Volume',project.volume],['Sumber dana',project.funding],['Pelaksana',project.executor],['Jadwal',project.schedule],['Progres fisik',project.progress==null?'':`${project.progress}%`],['Realisasi belanja',project.spent?money(project.spent):'']].forEach(([label,value])=>{if(value) {const row=document.createElement('div');row.className='bl-overlay-row';row.append(safeNode('span','',label),safeNode('strong','',value));overlay.append(row)}});detail.addEventListener('click',()=>overlay.classList.add('open'));overlay.addEventListener('click',event=>{if(event.target===overlay)overlay.classList.remove('open')});card.append(overlay);grid.append(card)})}
        fetch('/api/desa/brumbungan-lor/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>renderProjects(Array.isArray(data.projects)?data.projects:[])).catch(()=>renderProjects([],'Informasi pembangunan belum dapat dimuat saat ini.'));
        const budgetYear=document.querySelector('#budget-year'),budgetLines=document.querySelector('#budget-lines'),realized=document.querySelector('#budget-realized');let budgets=[];
        function renderBudget(year){const budget=budgets.find(item=>String(item.year)===String(year));if(!budget)return;const values=[['Dana Desa',budget.villageFund],['Alokasi Dana Desa',budget.villageAllocation],['Bagi Hasil Pajak',budget.taxRevenueShare],['Bagi Hasil Retribusi',budget.retributionShare]];budgetLines.replaceChildren(...values.map(([label,value])=>{const row=document.createElement('div');row.className='bl-budget-line';row.append(safeNode('span','',label),safeNode('strong','',value>0?money(value):'Belum tersedia'));return row}));realized.textContent='Belum tersedia'}budgetYear.addEventListener('change',()=>renderBudget(budgetYear.value));fetch('/api/desa/brumbungan-lor/budgets').then(response=>response.ok?response.json():Promise.reject()).then(data=>{budgets=data;if(!budgets.length)return;budgetYear.hidden=false;budgets.forEach(item=>{const option=document.createElement('option');option.value=item.year;option.textContent=String(item.year);budgetYear.append(option)});budgetYear.value=String(budgets[0].year);renderBudget(budgetYear.value)}).catch(()=>{});
        const nav=document.querySelector('#bl-nav'),menu=document.querySelector('#bl-menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});nav.addEventListener('click',event=>{if(event.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
        const questions=[{key:'title',label:'Judul usulan',prompt:'Apa kebutuhan yang ingin disampaikan?',required:true,type:'text'},{key:'location',label:'Lokasi',prompt:'Di mana kebutuhan ini berada?',required:true,type:'text'},{key:'category',label:'Bidang',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Pertanian dan irigasi','Lingkungan','Sosial','Lainnya']},{key:'description',label:'Uraian',prompt:'Ceritakan kondisi dan dampaknya bagi warga.',required:true,type:'textarea'},{key:'name',label:'Nama',prompt:'Nama yang boleh dicantumkan?',required:false,type:'text'},{key:'contact',label:'Kontak',prompt:'Nomor telepon untuk klarifikasi?',required:false,type:'text'}];let answers={},step=0;const chat=document.querySelector('#bl-chat'),messages=document.querySelector('#chat-messages'),controls=document.querySelector('#chat-controls'),actions=document.querySelector('#chat-actions'),error=document.querySelector('#chat-error'),toggle=document.querySelector('#chat-toggle');
        function say(text,isUser=false){messages.append(safeNode('div',`bl-chat-message${isUser?' is-user':''}`,text));messages.scrollTop=messages.scrollHeight}function action(label,handler,primary=false){const button=safeNode('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function closeChat(clear=true){chat.classList.remove('open');chat.setAttribute('aria-hidden','true');toggle.setAttribute('aria-expanded','false');if(clear){answers={};step=0;messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();error.textContent=''}}
        function renderQuestion(){controls.replaceChildren();actions.replaceChildren();error.textContent='';if(step>=questions.length){say('Periksa kembali usulan sebelum dikirim.');say(`Judul: ${answers.title}\nLokasi: ${answers.location}\nUraian: ${answers.description}`);actions.append(action('Batal',()=>closeChat()),action('Kirim usulan',submitProposal,true));return}const question=questions[step];say(question.prompt);controls.append(safeNode('div','bl-chat-prompt',`${step+1} dari ${questions.length} · ${question.label}`));if(question.type==='choice'){const options=document.createElement('div');options.className='bl-chat-options';question.options.forEach(option=>options.append(action(option,()=>{answers[question.key]=option;say(option,true);step++;renderQuestion()})));controls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='bl-chat-input';input.placeholder=question.label;input.setAttribute('aria-label',question.label);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;controls.append(input)}actions.append(action('Batal',()=>closeChat()));if(!question.required)actions.append(action('Lewati',()=>{answers[question.key]='';step++;renderQuestion()}));actions.append(action(step===questions.length-1?'Tinjau':'Lanjut',()=>{const input=controls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){error.textContent='Bagian ini perlu diisi.';return}answers[question.key]=value;if(value)say(value,true);step++;renderQuestion()},true))}
        async function submitProposal(){error.textContent='';const submit=actions.querySelector('.primary');submit.disabled=true;try{const response=await fetch('/api/desa/brumbungan-lor/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...answers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');messages.replaceChildren();controls.replaceChildren();actions.replaceChildren();say(result.message||'Usulan berhasil dikirim.');actions.append(action('Selesai',()=>closeChat(),true))}catch(exception){error.textContent=exception.message;submit.disabled=false}}
        toggle.addEventListener('click',()=>{chat.classList.add('open');chat.setAttribute('aria-hidden','false');toggle.setAttribute('aria-expanded','true');if(!messages.childElementCount)renderQuestion()});document.querySelector('#chat-close').addEventListener('click',()=>closeChat(false));document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelectorAll('.bl-project-overlay.open').forEach(overlay=>overlay.classList.remove('open'));if(chat.classList.contains('open'))closeChat(false)}});
    </script>
    @include('desa.partials.managed-content')
    @include('desa.partials.responsive')
</body>
</html>
